package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;

/**
 * 依赖声明：闭区间 [minimumVersion, maximumVersion]，版本均为正整数。
 *
 * @param scope 依赖作用域：PUBLIC 或 PRIVATE（大小写不敏感），缺省为 PUBLIC
 */
public record DependencySpec(
        @NotBlank String name,
        @Positive int minimumVersion,
        @Positive int maximumVersion,
        String scope) {

    /** 兼容旧调用：未声明作用域时默认 PUBLIC。 */
    public DependencySpec(String name, int minimumVersion, int maximumVersion) {
        this(name, minimumVersion, maximumVersion, null);
    }
}

package com.example.starter.api.dto;

/**
 * 响应中的依赖区间视图。
 *
 * @param scope 依赖作用域：PUBLIC 或 PRIVATE；旧依赖默认 PUBLIC
 */
public record DependencyView(String name, int minimumVersion, int maximumVersion, String scope) {

    /** 兼容旧调用：未声明作用域时默认 PUBLIC。 */
    public DependencyView(String name, int minimumVersion, int maximumVersion) {
        this(name, minimumVersion, maximumVersion, "PUBLIC");
    }
}

package com.example.starter.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 制品登记请求：name 与正整数 version 联合唯一，依赖 0～10 条。
 *
 * @param expectedRepositoryVersion 期望的仓库版本号；为 null 表示不校验，
 *                                  非 null 时与当前仓库版本不一致返回 409
 */
public record RegisterArtifactRequest(
        @NotBlank String name,
        @Positive int version,
        @Valid @Size(max = 10) List<@Valid DependencySpec> dependencies,
        @PositiveOrZero Long expectedRepositoryVersion) {

    /** 兼容旧调用：不携带期望仓库版本号。 */
    public RegisterArtifactRequest(String name, int version, List<DependencySpec> dependencies) {
        this(name, version, dependencies, null);
    }

    public RegisterArtifactRequest {
        if (dependencies == null) {
            dependencies = List.of();
        } else {
            dependencies = List.copyOf(dependencies);
        }
    }
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.PositiveOrZero;

/**
 * 撤回请求体（可选）：携带期望的仓库版本号。
 *
 * @param expectedRepositoryVersion 期望的仓库版本号；为 null 表示不校验，
 *                                  非 null 时与当前仓库版本不一致返回 409
 */
public record WithdrawRequest(@PositiveOrZero Long expectedRepositoryVersion) {
}

